    async finishFileUpload(authToken:string) {
        const response = await this.request.post('/api/v2/user/file-upload-finished', {
            headers: {
                "Authorization": authToken,
                "Content-Type": "application/json",
            },
        });

        return response;
    }

    // 📌 Метод получения JSON-ответа
    async getFileUploadResult(authToken: string) {
        const response = await this.finishFileUpload(authToken);
        expect(response.status()).toBe(200);
        return response.json();
    }
